1508	/// One publish attachment resolved to its canonical on-disk filename and its
1509	/// `versions[version].dist` block.
1510	struct PreparedAttachment {
1511	    attachment: PendingAttachment,
1512	    /// Canonical on-disk filename.
1513	    canonical: String,
1514	    /// The matching `dist` block, or `Value::Null` when absent.
1515	    dist: Value,
1516	}
