1518	async fn validate_publish_doc(
1519	    state: &AppState,
1520	    identity: &Identity,
1521	    name: PackageName,
1522	    mut incoming: Value,
1523	) -> Result<ValidatedPublish, RegistryError> {
1524	    authorize(state, identity, name.as_str(), Action::Publish)?;
1525	
1526	    let attachments = extract_attachments(&mut incoming)?;
1527	
1528	    // Resolve each attachment's canonical disk filename + matching
1529	    // `versions[v].dist` block. Attachment names that don't match the
1530	    // package (`bar-1.0.0.tgz` for `foo`) or that try to escape the
1531	    // package dir (`../../etc/passwd.tgz`) are rejected here, before
1532	    // any I/O. The canonical name is what we actually persist — for
1533	    // scoped libnpmpublish bodies the wire form is `@scope/name-version.tgz`
1534	    // but on disk it lives at `<root>/@scope/name/name-version.tgz`,
1535	    // matching what `serve_tarball` expects.
1536	    let mut prepared: Vec<PreparedAttachment> = Vec::with_capacity(attachments.len());
1537	    for attachment in attachments {
1538	        let (canonical, version) = name.parse_tarball_name(&attachment.filename)?;
1539	        let dist = incoming
1540	            .get("versions")
1541	            .and_then(|versions| versions.get(&version))
1542	            .and_then(|manifest| manifest.get("dist"))
1543	            .cloned()
1544	            .unwrap_or(Value::Null);
1545	        prepared.push(PreparedAttachment { attachment, canonical, dist });
1546	    }
1547	    Ok(ValidatedPublish { name, incoming, prepared })
1548	}
