1550	/// A publish whose packument is merged and whose tarballs are fully
1551	/// written to tmp slots — everything verified, nothing visible to
1552	/// readers yet. [`commit_publishes`] makes it visible.
1553	struct StagedPublish {
1554	    name: PackageName,
1555	    merged_bytes: Vec<u8>,
1556	    slots: Vec<crate::storage::TarballSlot>,
1557	}
1558	
1559	/// Merge the incoming packument with the on-disk / upstream state
1560	/// and stream every tarball to a tmp slot. The caller must hold the
1561	/// package lock for `doc.name` from before this call until after
1562	/// [`commit_publishes`]. On error, every tmp file this call wrote is
1563	/// removed.
1564	async fn stage_publish(
1565	    state: &AppState,
1566	    doc: ValidatedPublish,
1567	    now_iso: &str,
1568	) -> Result<StagedPublish, RegistryError> {
1569	    let ValidatedPublish { name, incoming, prepared } = doc;
1570	
1571	    let hosted_bytes = state.inner.storage.read_hosted_packument(&name).await?;
1572	
1573	    // Reject a re-publish of an already-hosted version: published versions
1574	    // are immutable, and npm/verdaccio answer a re-publish with 409. Check
1575	    // every version in the incoming body — not just the ones backed by an
1576	    // attachment, since merge_manifest below consumes the whole `versions`
1577	    // map — against the locally hosted packument only (a version that exists
1578	    // only upstream may still be published here for the first time).
1579	    if let Some(bytes) = hosted_bytes.as_deref() {
1580	        let hosted: Value = serde_json::from_slice(bytes).map_err(RegistryError::Json)?;
1581	        if let Some(hosted_versions) = hosted.get("versions").and_then(Value::as_object)
1582	            && let Some(incoming_versions) = incoming.get("versions").and_then(Value::as_object)
1583	            && let Some(clash) =
1584	                incoming_versions.keys().find(|version| hosted_versions.contains_key(*version))
1585	        {
1586	            return Err(RegistryError::VersionAlreadyPublished {
1587	                package: name.as_str().to_string(),
1588	                version: clash.clone(),
1589	            });
1590	        }
1591	    }
1592	
1593	    // Seed the merge from whatever the upstream knows about the
1594	    // package, not just from a cold cache. Without this, a publish
1595	    // of a brand-new version of an upstream-only package would
1596	    // start from `None` and the newly-written local packument
1597	    // would mask every upstream version + dist-tag on subsequent
1598	    // reads. `update_dist_tag` already does the same fallback —
1599	    // we just mirror it here.
1600	    let existing_bytes = match hosted_bytes {
1601	        Some(bytes) => Some(bytes),
1602	        None => match load_packument_bytes(state, &name).await {
1603	            PackumentLoad::Ok(bytes) => Some(bytes),
1604	            PackumentLoad::NotFound => None,
1605	            PackumentLoad::Err(err) => return Err(err),
1606	        },
1607	    };
1608	    let existing: Option<Value> = match existing_bytes.as_deref().map(serde_json::from_slice) {
1609	        Some(Ok(v)) => Some(v),
1610	        Some(Err(err)) => return Err(RegistryError::Json(err)),
1611	        None => None,
1612	    };
1613	    let merged = merge_manifest(existing.as_ref(), &incoming, now_iso);
1614	    let merged_bytes = serde_json::to_vec_pretty(&merged).map_err(RegistryError::Json)?;
