1621	    // missing integrity field — short-circuits the publish with a
1622	    // 400; any tmp files written before the failure get removed
1623	    // along the way so a bad upload leaves no on-disk artifact.
1624	    let mut written_slots = Vec::with_capacity(prepared.len());
