1761	            .status(StatusCode::OK)
1762	            .header(header::CONTENT_TYPE, "application/json")
1763	            .body(Body::from(bytes))
1764	            .expect("static-shape response always builds");
1765	    };
1766	    let size = crate::search::parse_size(query_string, 20);
1767	    let mut body = match crate::search::run_local_search(&state.inner.storage, &text, size).await {
