207	/// Re-apply a sealed transaction. Every step tolerates having already
208	/// run before the crash: a tmp file that's gone was already promoted,
209	/// and the packument is re-merged into the current on-disk state
210	/// instead of overwriting it.
211	async fn roll_forward(storage: &Storage, dir: &Path) -> Result<()> {
212	    let manifest: Manifest = serde_json::from_slice(&fs::read(dir.join(MANIFEST_FILE)).await?)?;
213	    for package in &manifest.packages {
214	        let name = PackageName::parse(&package.name)?;
215	        for tarball in &package.tarballs {
216	            // A missing tmp file was already promoted before the crash, so
217	            // skip it. But never read an I/O error as "missing": that would
218	            // skip promotion, write the packument anyway, and delete the
219	            // journal entry — advertising a tarball with nothing on disk and
220	            // no journal state left to retry from. Propagate it instead so
221	            // recovery aborts and the entry survives for a later attempt.
222	            if fs::try_exists(&tarball.tmp_path).await? {
223	                let slot = TarballSlot::from_parts(
224	                    tarball.tmp_path.clone(),
225	                    name.clone(),
226	                    tarball.filename.clone(),
227	                );
228	                storage.finalize_tarball_slot(slot).await?;
229	            }
230	        }
231	        let journaled: serde_json::Value =
232	            serde_json::from_slice(&fs::read(dir.join(&package.packument_file)).await?)?;
233	        let existing: Option<serde_json::Value> = match storage.read_hosted_packument(&name).await?
