235	            Some(bytes) => Some(serde_json::from_slice(&bytes)?),
236	            None => None,
237	        };
238	        let merged = merge_manifest(existing.as_ref(), &journaled, &now_iso());
239	        storage.write_hosted_packument(&name, &serde_json::to_vec_pretty(&merged)?).await?;
240	    }
241	    fs::remove_dir_all(dir).await?;
242	    Ok(())
