/// `deprecated` field. A non-object incoming entry (e.g. `null`) leaves the
/// hosted version untouched.
fn preserve_hosted_version(hosted_entry: &Value, incoming_entry: &Value) -> Value {
    let Some(hosted_obj) = hosted_entry.as_object() else {
        return hosted_entry.clone();
    };
    let mut preserved = hosted_obj.clone();
    if let Some(incoming_obj) = incoming_entry.as_object() {
        match incoming_obj.get("deprecated") {
            Some(deprecated) => {
                preserved.insert("deprecated".to_string(), deprecated.clone());
            }
            None => {
                preserved.remove("deprecated");
            }
        }
    }
